'use strict'

//note(dgmid): locale-aware (case / accent / Ñ-insensitive) folder name comparison.
//Plain code-point compares ("a" > "Z", "á" after "z") make alphabetised lists look
//wrong for Spanish/other Latin-script names, so every folder picker sorts with this.

const _collator = ( typeof Intl !== 'undefined' && Intl.Collator )
	? new Intl.Collator( undefined, { numeric: true, sensitivity: 'base' } )
	: null

function _compareText( a, b ) {
	
	if( _collator ) return _collator.compare( a.text, b.text )
	
	let x = String( a.text ).toLowerCase(),
		y = String( b.text ).toLowerCase()
	
	return ( x > y ) ? 1 : ( ( x < y ) ? -1 : 0 )
}

//note(dgmid): build an indented tree list from the flat folder array.
//The store's folder items are { id, text, parent_folder } where parent_folder
//is -1 (or null) for root folders. This helper returns a list of
//{ id, text, depth } ordered parents-before-children, ready to be rendered
//as an indented <select> or select2 dropdown.

//note(dgmid): collect all descendant ids of a folder (used to exclude the folder
//and its whole subtree from drop targets / parent dropdowns to avoid cycles).
//Works with numeric or string ids.

module.exports.getDescendants = function ( folders, rootId ) {
	
	let root = parseInt( rootId, 10 ),
		descendants = new Set(),
		toVisit = [ root ]
	
	while( toVisit.length > 0 ) {
		
		let current = toVisit.pop()
		
		for( let f of folders ) {
			
			if( parseInt( f.parent_folder, 10 ) === current && !descendants.has( f.id ) ) {
				
				descendants.add( f.id )
				toVisit.push( parseInt( f.id, 10 ) )
			}
		}
	}
	
	return descendants
}



module.exports.buildHierarchyList = function ( folders, excluded ) {
	
	folders 	= folders || []
	excluded 	= excluded || new Set()
	
	let map = {}
	
	for( let folder of folders ) {
		
		if( excluded.has( folder.id ) ) continue
		
		map[ folder.id ] = {
			id: folder.id,
			text: folder.text,
			parent_folder: ( folder.parent_folder == null || folder.parent_folder === -1 || folder.parent_folder === '-1' ) ? null : folder.parent_folder,
			children: []
		}
	}
	
	//note(dgmid): attach each folder to its parent; orphans / roots go to the top level.
	//Iterate the original array (not Object.keys) so siblings keep their source order.
	
	let roots = []
	
	for( let folder of folders ) {
		
		if( excluded.has( folder.id ) ) continue
		
		let node = map[ folder.id ]
		
		if( node.parent_folder != null && map[ node.parent_folder ] ) {
			
			map[ node.parent_folder ].children.push( node )
			
		} else {
			
			roots.push( node )
		}
	}
	
	let result = []
	
	function walk( node, depth ) {
		
		result.push( { id: node.id, text: node.text, depth: depth } )
		
		//note(dgmid): siblings are sorted alphabetically (locale-aware) at every level,
		//so every folder picker / parent dropdown shows a predictable A→Z list instead
		//of the arbitrary order the server happens to return.
		node.children.sort( _compareText )
		
		for( let child of node.children ) {
			
			walk( child, depth + 1 )
		}
	}
	
	roots.sort( _compareText )
	
	for( let root of roots ) {
		
		walk( root, 0 )
	}
	
	return result
}
